    /// <summary>
    /// Checks whether the current user can message another user or try to create a chat with them
    /// </summary>
    public Task<TdLib.TdApi.Objects.CanSendMessageToUserResult> CanSendMessageToUserAsync(long userId = default, bool onlyLocal = default)
    {

           using var activity =  StartCallActivity("CanSendMessageToUserAsync", typeof(CanSendMessageToUser).FullName ?? "CanSendMessageToUserAsync");

           try
           {
             return client.CanSendMessageToUserAsync(userId, onlyLocal);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
